#!/usr/bin/env python3
"""Minimal VT100/xterm screen parser.

Parses a raw PTY byte stream (as captured by /tmp/tj/harness.py) into a
character + attribute grid, including support for the xterm alternate
screen buffer, SGR attributes, cursor movement, erasing, and common
private modes. Wide chars (CJK) are NOT specially handled; the app under
test appears ASCII-only in its UI chrome.

Usage:
    import sys; sys.path.insert(0, "/tmp/tj")
    from harness import run
    from vtparse import Screen
    out = run(["/workspace/executable"], env_extra={"HOME": "/tmp/tj/x"})
    s = Screen(24, 80)
    s.feed(out)
    print(s.text())            # plain text grid
    print(s.text_with_attrs()) # annotated with attribute runs per line
"""
import re

# Attribute model: (fg, bg, bold, dim, italic, underline, strike, blink, reverse, hidden)
# fg/bg: None (default), int 0-255 (palette), or (r,g,b) tuple.

class Cell:
    __slots__ = ("ch", "attr")
    def __init__(self, ch=" ", attr=None):
        self.ch = ch
        self.attr = attr

DEFAULT_ATTR = (None, None, False, False, False, False, False, False, False, False)

def attr_str(a):
    fg, bg, bold, dim, it, ul, st, bl, rev, hid = a
    parts = []
    if fg is not None: parts.append(f"fg={fg}")
    if bg is not None: parts.append(f"bg={bg}")
    if bold: parts.append("bold")
    if dim: parts.append("dim")
    if it: parts.append("italic")
    if ul: parts.append("underline")
    if st: parts.append("strike")
    if bl: parts.append("blink")
    if rev: parts.append("reverse")
    if hid: parts.append("hidden")
    return ",".join(parts) if parts else "default"


class Screen:
    def __init__(self, rows=24, cols=80):
        self.rows = rows
        self.cols = cols
        self.main = [[Cell() for _ in range(cols)] for _ in range(rows)]
        self.alt = None  # becomes grid when alternate screen active
        self.cur_r = 0
        self.cur_c = 0
        self.saved = (0, 0, DEFAULT_ATTR)
        self.attr = DEFAULT_ATTR
        self.using_alt = False
        self.cursor_visible = True
        self.modes = set()  # private modes set
        self.wrap_pending = False

    @property
    def grid(self):
        return self.alt if self.using_alt else self.main

    def _blank_row(self):
        return [Cell() for _ in range(self.cols)]

    def _ensure_alt(self):
        if self.alt is None:
            self.alt = [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]

    def resize_grid(self, rows, cols):
        # not typically needed; keep simple
        self.rows, self.cols = rows, cols
        self.main = [[Cell() for _ in range(cols)] for _ in range(rows)]
        self.alt = None

    def put(self, ch):
        g = self.grid
        if self.wrap_pending:
            self.cur_c = 0
            self.cur_r += 1
            if self.cur_r >= self.rows:
                g.pop(0)
                g.append(self._blank_row())
                self.cur_r = self.rows - 1
            self.wrap_pending = False
        if 0 <= self.cur_r < self.rows and 0 <= self.cur_c < self.cols:
            g[self.cur_r][self.cur_c] = Cell(ch, self.attr)
        self.cur_c += 1
        if self.cur_c >= self.cols:
            self.cur_c = self.cols - 1
            self.wrap_pending = True

    def erase_line(self, mode):
        g = self.grid
        r, c = self.cur_r, self.cur_c
        if mode == 0:
            rng = range(c, self.cols)
        elif mode == 1:
            rng = range(0, c + 1)
        else:
            rng = range(0, self.cols)
        for cc in rng:
            g[r][cc] = Cell()

    def erase_screen(self, mode):
        g = self.grid
        if mode == 0:
            for r in range(self.cur_r, self.rows):
                start = self.cur_c if r == self.cur_r else 0
                for c in range(start, self.cols):
                    g[r][c] = Cell()
        elif mode == 1:
            for r in range(0, self.cur_r + 1):
                end = self.cur_c if r == self.cur_r else self.cols - 1
                for c in range(0, end + 1):
                    g[r][c] = Cell()
        else:
            for r in range(self.rows):
                for c in range(self.cols):
                    g[r][c] = Cell()

    def scroll_up(self, n):
        g = self.grid
        for _ in range(n):
            g.pop(0)
            g.append(self._blank_row())

    def scroll_down(self, n):
        g = self.grid
        for _ in range(n):
            g.pop()
            g.insert(0, self._blank_row())

    def handle_sgr(self, params):
        if not params:
            params = [0]
        fg, bg, bold, dim, it, ul, st, bl, rev, hid = self.attr
        i = 0
        while i < len(params):
            p = params[i]
            if p == 0:
                fg, bg, bold, dim, it, ul, st, bl, rev, hid = DEFAULT_ATTR
            elif p == 1: bold = True
            elif p == 2: dim = True
            elif p == 3: it = True
            elif p == 4: ul = True
            elif p == 5: bl = True
            elif p == 7: rev = True
            elif p == 8: hid = True
            elif p == 9: st = True
            elif p == 22: bold = dim = False
            elif p == 23: it = False
            elif p == 24: ul = False
            elif p == 25: bl = False
            elif p == 27: rev = False
            elif p == 28: hid = False
            elif p == 29: st = False
            elif 30 <= p <= 37: fg = p - 30
            elif p == 38:
                if i + 1 < len(params) and params[i+1] == 5 and i + 2 < len(params):
                    fg = params[i+2]; i += 2
                elif i + 1 < len(params) and params[i+1] == 2 and i + 4 < len(params):
                    fg = (params[i+2], params[i+3], params[i+4]); i += 4
            elif p == 39: fg = None
            elif 40 <= p <= 47: bg = p - 40
            elif p == 48:
                if i + 1 < len(params) and params[i+1] == 5 and i + 2 < len(params):
                    bg = params[i+2]; i += 2
                elif i + 1 < len(params) and params[i+1] == 2 and i + 4 < len(params):
                    bg = (params[i+2], params[i+3], params[i+4]); i += 4
            elif p == 49: bg = None
            elif 90 <= p <= 97: fg = p - 90 + 8
            elif 100 <= p <= 107: bg = p - 100 + 8
            i += 1
        self.attr = (fg, bg, bold, dim, it, ul, st, bl, rev, hid)

    def handle_csi(self, params, intermediates, final):
        priv = intermediates.startswith("?")
        def p(i, d=1):
            if i < len(params) and params[i] != 0 and params[i] is not None:
                return params[i]
            return d
        if final == "A": self.cur_r = max(0, self.cur_r - p(0))
        elif final == "B": self.cur_r = min(self.rows - 1, self.cur_r + p(0))
        elif final == "C": self.cur_c = min(self.cols - 1, self.cur_c + p(0))
        elif final == "D": self.cur_c = max(0, self.cur_c - p(0))
        elif final == "E": self.cur_r = min(self.rows - 1, self.cur_r + p(0)); self.cur_c = 0
        elif final == "F": self.cur_r = max(0, self.cur_r - p(0)); self.cur_c = 0
        elif final == "G" or final == "`": self.cur_c = min(self.cols - 1, p(0) - 1)
        elif final == "d": self.cur_r = min(self.rows - 1, p(0) - 1)
        elif final == "H" or final == "f":
            self.cur_r = min(self.rows - 1, p(0) - 1)
            self.cur_c = min(self.cols - 1, p(1, 1) - 1)
        elif final == "J": self.erase_screen(params[0] if params else 0)
        elif final == "K": self.erase_line(params[0] if params else 0)
        elif final == "L":
            n = p(0)
            g = self.grid
            for _ in range(n):
                g.insert(self.cur_r, self._blank_row())
                g.pop()
        elif final == "M":
            n = p(0)
            g = self.grid
            for _ in range(n):
                g.pop(self.cur_r)
                g.append(self._blank_row())
        elif final == "P":
            n = p(0)
            g = self.grid
            r = self.cur_r
            for _ in range(n):
                if self.cur_c < self.cols:
                    g[r].pop(self.cur_c)
                    g[r].append(Cell())
        elif final == "S": self.scroll_up(p(0))
        elif final == "T": self.scroll_down(p(0))
        elif final == "X":
            g = self.grid
            for c in range(self.cur_c, min(self.cols, self.cur_c + p(0))):
                g[self.cur_r][c] = Cell()
        elif final == "s": self.saved = (self.cur_r, self.cur_c, self.attr)
        elif final == "u": self.cur_r, self.cur_c, _ = self.saved
        elif final == "m": self.handle_sgr(params)
        elif final == "h" or final == "l":
            seton = final == "h"
            for mode in params:
                if mode is None: continue
                if priv and mode in (1049, 1047, 47):
                    if seton:
                        self.using_alt = True
                        self._ensure_alt()
                        if mode == 1049:
                            self.alt = [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]
                            self.cur_r = self.cur_c = 0
                    else:
                        self.using_alt = False
                        if mode == 1049:
                            self.cur_r = self.cur_c = 0
                elif priv and mode == 25:
                    self.cursor_visible = seton
                elif priv and mode == 1:
                    pass  # application cursor keys
                else:
                    if seton: self.modes.add((priv, mode))
                    else: self.modes.discard((priv, mode))
        elif final == "r":
            pass  # scroll region; app doesn't use it per observations
        # else: ignore

    def feed(self, data: bytes):
        text = data.decode("utf-8", errors="replace")
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == "\x1b":
                if i + 1 >= n: break
                nxt = text[i+1]
                if nxt == "[":
                    m = re.match(r"\x1b\[([0-9;?]*)([=>!]?)([@-~])", text[i:])
                    if m:
                        ps, inter, final = m.groups()
                        params = []
                        for x in ps.split(";"):
                            if x == "" or x == "?":
                                params.append(None)
                            else:
                                try: params.append(int(x))
                                except ValueError: params.append(None)
                        if ps.startswith("?"):
                            self.handle_csi(params, "?", final)
                        else:
                            self.handle_csi(params, inter, final)
                        i += m.end()
                        continue
                    else:
                        i += 2
                        continue
                elif nxt == "]":  # OSC
                    m = re.match(r"\x1b\][^\x07\x1b]*(\x07|\x1b\\)", text[i:])
                    if m:
                        i += m.end()
                        continue
                    i += 2
                    continue
                elif nxt in "=>78":  # charset/keypad or DECSC/DECRC
                    if nxt == "7":
                        self.saved = (self.cur_r, self.cur_c, self.attr)
                    elif nxt == "8":
                        self.cur_r, self.cur_c, _ = self.saved
                    i += 2
                    continue
                elif nxt == "(" or nxt == ")":
                    i += 3
                    continue
                elif nxt == "M":  # reverse index
                    self.cur_r = max(0, self.cur_r - 1)
                    i += 2
                    continue
                elif nxt == "D":
                    self.cur_r = min(self.rows - 1, self.cur_r + 1)
                    i += 2
                    continue
                elif nxt == "E":
                    self.cur_r = min(self.rows - 1, self.cur_r + 1)
                    self.cur_c = 0
                    i += 2
                    continue
                elif nxt == "c":
                    i += 2
                    continue
                else:
                    i += 2
                    continue
            elif ch == "\r":
                self.cur_c = 0
                self.wrap_pending = False
                i += 1
            elif ch == "\n":
                self.cur_r = min(self.rows - 1, self.cur_r + 1)
                self.wrap_pending = False
                i += 1
            elif ch == "\b":
                self.cur_c = max(0, self.cur_c - 1)
                self.wrap_pending = False
                i += 1
            elif ch == "\t":
                self.cur_c = min(self.cols - 1, (self.cur_c // 8 + 1) * 8)
                self.wrap_pending = False
                i += 1
            elif ord(ch) < 32 or ch == "\x7f":
                i += 1
            else:
                self.put(ch)
                i += 1

    def text(self, rstrip=True):
        lines = []
        for row in self.grid:
            line = "".join(c.ch for c in row)
            if rstrip:
                line = line.rstrip()
            lines.append(line)
        return "\n".join(lines)

    def text_with_attrs(self):
        """Each line as text plus a list of (start,end,attrstr) runs for
        cells whose attr != default."""
        out = []
        for ri, row in enumerate(self.grid):
            line = "".join(c.ch for c in row)
            runs = []
            start = None
            cur = None
            for ci, c in enumerate(row):
                a = None if c.attr == DEFAULT_ATTR else c.attr
                if a != cur:
                    if cur is not None:
                        runs.append((start, ci, attr_str(cur)))
                    cur = a
                    start = ci if a is not None else None
            if cur is not None:
                runs.append((start, len(row), attr_str(cur)))
            out.append((line.rstrip(), runs))
        return out

    def dump(self, show_attrs=True, cursor=True):
        """Human-friendly dump: line number | text, then attr runs."""
        rows = self.text_with_attrs()
        parts = []
        for ri, (line, runs) in enumerate(rows):
            marker = ""
            if cursor and self.using_alt is not None and ri == self.cur_r:
                marker = f" <cursor col={self.cur_c}>"
            parts.append(f"{ri:2d}|{line}{marker}")
            if show_attrs:
                for (s, e, a) in runs:
                    seg = line[s:e] if s < len(line) else ""
                    parts.append(f"    [{s:2d}-{e:2d}] {a}  {seg!r}")
        if not self.cursor_visible:
            parts.append("(cursor hidden)")
        return "\n".join(parts)


if __name__ == "__main__":
    import sys
    data = open(sys.argv[1], "rb").read() if len(sys.argv) > 1 else sys.stdin.buffer.read()
    rows = int(sys.argv[2]) if len(sys.argv) > 2 else 24
    cols = int(sys.argv[3]) if len(sys.argv) > 3 else 80
    s = Screen(rows, cols)
    s.feed(data)
    print(s.dump())

