#!/usr/bin/env python3
"""Minimal VT100/xterm screen renderer for captured pty bytes.

Usage:
    from vtparse import Screen
    s = Screen(rows=24, cols=80)
    s.feed(data)
    print(s.render())          # plain text grid
    print(s.render_attrs())    # text + per-cell attr codes for non-default cells
    print(s.render_runs())     # text + per-line runs of uniform attrs

Attribute model: each cell carries a frozenset of strings, e.g.
    {"bold"}, {"fg=196"}, {"bg=(255,128,0)"}, {"fg2"}, {"rev"}, {"dim"}

Or CLI:  python3 vtparse.py file.raw [--rows 24 --cols 80] [--attrs] [--runs]
"""
import re, sys


class Cell:
    __slots__ = ("ch", "attrs")

    def __init__(self):
        self.ch = " "
        self.attrs = frozenset()


def _color_str(prefix, params, i):
    """Parse extended color starting at params[i] (38/48). Returns (token, new_i)."""
    if i + 1 < len(params) and params[i + 1] == 5 and i + 2 < len(params):
        return f"{prefix}={params[i + 2]}", i + 2
    if i + 1 < len(params) and params[i + 1] == 2 and i + 4 < len(params):
        return f"{prefix}=({params[i + 2]},{params[i + 3]},{params[i + 4]})", i + 4
    return None, i


class Screen:
    def __init__(self, rows=24, cols=80):
        self.rows = rows
        self.cols = cols
        self.grid = [[Cell() for _ in range(cols)] for _ in range(rows)]
        self.r = 0
        self.c = 0
        self.attrs = set()
        self.saved = (0, 0)
        self.cursor_visible = True

    def feed(self, data: bytes):
        text = data.decode("utf-8", errors="replace")
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == "\x1b":
                m = re.match(r"\x1b\[([0-9;?]*)([@-~])", text[i:])
                if m:
                    params, final = m.group(1), m.group(2)
                    self._csi(params, final)
                    i += m.end()
                    continue
                m = re.match(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", text[i:])
                if m:  # OSC (title etc.) -- ignored
                    i += m.end()
                    continue
                m = re.match(r"\x1b([()][0-9A-B])", text[i:])
                if m:
                    i += m.end()
                    continue
                m = re.match(r"\x1b([=>M78cDE])", text[i:])
                if m:
                    f = m.group(1)
                    if f == "7":
                        self.saved = (self.r, self.c)
                    elif f == "8":
                        self.r, self.c = self.saved
                    elif f == "M":
                        self.r = max(0, self.r - 1)
                    elif f == "D":
                        self._index()
                    elif f == "E":
                        self._index(); self.c = 0
                    i += m.end()
                    continue
                i += 1
                continue
            if ch == "\r":
                self.c = 0
            elif ch == "\n":
                self._index()
            elif ch == "\b":
                self.c = max(0, self.c - 1)
            elif ch == "\t":
                self.c = min(self.cols - 1, (self.c // 8 + 1) * 8)
            elif ch < " " or ch == "\x7f":
                pass
            else:
                if 0 <= self.r < self.rows and 0 <= self.c < self.cols:
                    cell = self.grid[self.r][self.c]
                    cell.ch = ch
                    cell.attrs = frozenset(self.attrs)
                self.c += 1
                if self.c >= self.cols:
                    self.c = self.cols - 1
            i += 1

    def _index(self):
        if self.r < self.rows - 1:
            self.r += 1

    def _sgr(self, nums):
        i = 0
        while i < len(nums):
            v = nums[i]
            if v == 0:
                self.attrs = set()
            elif v == 1:
                self.attrs.add("bold")
            elif v == 2:
                self.attrs.add("dim")
            elif v == 3:
                self.attrs.add("italic")
            elif v == 4:
                self.attrs.add("underline")
            elif v == 5:
                self.attrs.add("blink")
            elif v == 7:
                self.attrs.add("rev")
            elif v == 8:
                self.attrs.add("hidden")
            elif v == 9:
                self.attrs.add("strike")
            elif v == 22:
                self.attrs.discard("bold"); self.attrs.discard("dim")
            elif v == 23:
                self.attrs.discard("italic")
            elif v == 24:
                self.attrs.discard("underline")
            elif v == 25:
                self.attrs.discard("blink")
            elif v == 27:
                self.attrs.discard("rev")
            elif v == 28:
                self.attrs.discard("hidden")
            elif v == 29:
                self.attrs.discard("strike")
            elif 30 <= v <= 37:
                self.attrs = {a for a in self.attrs if not a.startswith("fg")}
                self.attrs.add(f"fg{v - 30}")
            elif v == 38:
                tok, i = _color_str("fg", nums, i)
                if tok:
                    self.attrs = {a for a in self.attrs if not a.startswith("fg")}
                    self.attrs.add(tok)
            elif v == 39:
                self.attrs = {a for a in self.attrs if not a.startswith("fg")}
            elif 40 <= v <= 47:
                self.attrs = {a for a in self.attrs if not a.startswith("bg")}
                self.attrs.add(f"bg{v - 40}")
            elif v == 48:
                tok, i = _color_str("bg", nums, i)
                if tok:
                    self.attrs = {a for a in self.attrs if not a.startswith("bg")}
                    self.attrs.add(tok)
            elif v == 49:
                self.attrs = {a for a in self.attrs if not a.startswith("bg")}
            elif 90 <= v <= 97:
                self.attrs = {a for a in self.attrs if not a.startswith("fg")}
                self.attrs.add(f"fgb{v - 90}")
            elif 100 <= v <= 107:
                self.attrs = {a for a in self.attrs if not a.startswith("bg")}
                self.attrs.add(f"bgb{v - 100}")
            i += 1

    def _csi(self, params, final):
        p = params
        nums = [int(x) if x else 0 for x in p.lstrip("?").split(";")] if p else []
        is_priv = p.startswith("?")
        if final in "Hf":
            r = (nums[0] if len(nums) > 0 and nums[0] else 1) - 1
            c = (nums[1] if len(nums) > 1 and nums[1] else 1) - 1
            self.r = max(0, min(self.rows - 1, r))
            self.c = max(0, min(self.cols - 1, c))
        elif final == "A":
            self.r = max(0, self.r - (nums[0] or 1 if nums else 1))
        elif final == "B":
            self.r = min(self.rows - 1, self.r + (nums[0] or 1 if nums else 1))
        elif final == "C":
            self.c = min(self.cols - 1, self.c + (nums[0] or 1 if nums else 1))
        elif final == "D":
            self.c = max(0, self.c - (nums[0] or 1 if nums else 1))
        elif final == "G":
            self.c = max(0, min(self.cols - 1, (nums[0] or 1) - 1))
        elif final == "d":
            self.r = max(0, min(self.rows - 1, (nums[0] or 1) - 1))
        elif final == "J":
            mode = nums[0] if nums else 0
            if mode == 2 or mode == 3:
                self.grid = [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]
            elif mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = Cell()
                for rr in range(self.r + 1, self.rows):
                    self.grid[rr] = [Cell() for _ in range(self.cols)]
        elif final == "K":
            mode = nums[0] if nums else 0
            if mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = Cell()
            elif mode == 1:
                for cc in range(0, self.c + 1):
                    self.grid[self.r][cc] = Cell()
            elif mode == 2:
                self.grid[self.r] = [Cell() for _ in range(self.cols)]
        elif final == "m":
            if not nums:
                nums = [0]
            self._sgr(nums)
        elif final == "s":
            self.saved = (self.r, self.c)
        elif final == "u":
            self.r, self.c = self.saved
        elif final in "hl" and is_priv:
            # alt screen / cursor visibility etc. -- clear on alt-screen enter
            if 1049 in nums and final == "h":
                self.grid = [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]
                self.r = self.c = 0
            if 25 in nums:
                self.cursor_visible = (final == "h")

    def render(self, rstrip=True):
        lines = []
        for row in self.grid:
            line = "".join(c.ch for c in row)
            lines.append(line.rstrip() if rstrip else line)
        return "\n".join(lines)

    def render_attrs(self):
        """Render text, then list cells with non-default attrs as (row,col,ch,attrs)."""
        out = [self.render(), "", "--- non-default attr cells (1-based row,col) ---"]
        for ri, row in enumerate(self.grid, 1):
            for ci, cell in enumerate(row, 1):
                if cell.attrs:
                    out.append(f"({ri},{ci}) {cell.ch!r} {sorted(cell.attrs)}")
        return "\n".join(out)

    def render_runs(self):
        """Render text, then per-line runs of uniform non-default attrs."""
        out = [self.render(), "", "--- attr runs per line (1-based rows) ---"]
        for ri, row in enumerate(self.grid, 1):
            runs = []
            start = None
            cur = frozenset()
            for ci, cell in enumerate(row):
                if cell.attrs != cur:
                    if cur:
                        runs.append((start + 1, ci, "".join(c.ch for c in row[start:ci]), sorted(cur)))
                    start = ci
                    cur = cell.attrs
            if cur:
                runs.append((start + 1, len(row), "".join(c.ch for c in row[start:]), sorted(cur)))
            for s, e, txt, a in runs:
                out.append(f"row {ri} cols {s}-{e}: {txt!r} {a}")
        return "\n".join(out)


if __name__ == "__main__":
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--rows", type=int, default=24)
    ap.add_argument("--cols", type=int, default=80)
    ap.add_argument("--attrs", action="store_true")
    ap.add_argument("--runs", action="store_true")
    a = ap.parse_args()
    s = Screen(a.rows, a.cols)
    with open(a.file, "rb") as f:
        s.feed(f.read())
    if a.runs:
        print(s.render_runs())
    elif a.attrs:
        print(s.render_attrs())
    else:
        print(s.render())

